module Aihc.Tc.Deriving.References (DerivingReference(..), ReferencePackage(..), DerivingReferences(..), GenericReferences(..), StockClassLocation(..), referenceIdentity, stockClassLocationMatches, derivingReferenceList, genericTermReferences) where {
import Aihc.Parser.Syntax (NameType(..));
import Aihc.Resolve (PackageId(..), ResolutionNamespace(..));
import Data.Text (Text);
data DerivingReference = DerivingReference { referencePackage :: !ReferencePackage, referenceModule :: !Text, referenceName :: !Text, referenceNameType :: !NameType, referenceNamespace :: !ResolutionNamespace } deriving (Eq, Show);
data ReferencePackage = ReferencePrimPackage | ReferenceClassPackage deriving (Eq, Show);
data StockClassLocation = StockClassLocation { stockLocationPackage :: !(Maybe PackageId), stockLocationModule :: !Text, stockLocationName :: !Text } deriving (Eq, Show);
referenceIdentity :: PackageId -> PackageId -> DerivingReference -> (PackageId, Text, Text);
referenceIdentity primPackage classPackage reference = (package, referenceModule reference, referenceName reference) where {
  package = case referencePackage reference of {
  ReferencePrimPackage -> primPackage;
  ReferenceClassPackage -> classPackage}};
stockClassLocationMatches :: (Text, Text) -> StockClassLocation -> Text -> Bool;
stockClassLocationMatches (packageIdentity, moduleName) location className = maybe True (== PackageId packageIdentity) (stockLocationPackage location) && moduleName == stockLocationModule location && className == stockLocationName location;
data DerivingReferences = DerivingReferences { derivingTrue :: !DerivingReference, derivingFalse :: !DerivingReference, derivingLT :: !DerivingReference, derivingEQ :: !DerivingReference, derivingGT :: !DerivingReference, derivingIntCon :: !DerivingReference, derivingIntPrimType :: !DerivingReference, derivingGreaterOrEqual :: !DerivingReference, derivingCons :: !DerivingReference, derivingBind :: !DerivingReference, derivingThen :: !DerivingReference, derivingReturn :: !DerivingReference, derivingReadParens :: !DerivingReference, derivingReadPrecContext :: !DerivingReference, derivingReadStep :: !DerivingReference, derivingReadReset :: !DerivingReference, derivingReadAlternative :: !DerivingReference, derivingReadFail :: !DerivingReference, derivingReadExpect :: !DerivingReference, derivingReadField :: !DerivingReference, derivingReadSymField :: !DerivingReference, derivingLexemeIdent :: !DerivingReference, derivingLexemeSymbol :: !DerivingReference, derivingLexemePunc :: !DerivingReference, derivingPure :: !DerivingReference, derivingApply :: !DerivingReference, derivingLiftConE :: !DerivingReference, derivingLiftAppE :: !DerivingReference, derivingLiftDataConName :: !DerivingReference, derivingLiftCodeCoerce :: !DerivingReference, derivingGeneric :: !GenericReferences, derivingStockClasses :: ![StockClassLocation], derivingRecognizedClasses :: ![(Text, Text)] } deriving (Eq, Show);
data GenericReferences = GenericReferences { genericM1 :: !DerivingReference, genericUnM1 :: !DerivingReference, genericK1 :: !DerivingReference, genericUnK1 :: !DerivingReference, genericU1 :: !DerivingReference, genericL1 :: !DerivingReference, genericR1 :: !DerivingReference, genericProduct :: !DerivingReference, genericV1Type :: !DerivingReference, genericU1Type :: !DerivingReference, genericSumType :: !DerivingReference, genericProductType :: !DerivingReference, genericD1Type :: !DerivingReference, genericC1Type :: !DerivingReference, genericS1Type :: !DerivingReference, genericRec0Type :: !DerivingReference, genericMetaData :: !DerivingReference, genericMetaCons :: !DerivingReference, genericMetaSel :: !DerivingReference, genericPrefixI :: !DerivingReference, genericInfixI :: !DerivingReference, genericLeftAssociative :: !DerivingReference, genericRightAssociative :: !DerivingReference, genericNotAssociative :: !DerivingReference, genericNoSourceUnpackedness :: !DerivingReference, genericSourceNoUnpack :: !DerivingReference, genericSourceUnpack :: !DerivingReference, genericNoSourceStrictness :: !DerivingReference, genericSourceLazy :: !DerivingReference, genericSourceStrict :: !DerivingReference, genericDecidedLazy :: !DerivingReference, genericDecidedStrict :: !DerivingReference, genericDecidedUnpack :: !DerivingReference } deriving (Eq, Show);
genericTermReferences :: [GenericReferences -> DerivingReference];
genericTermReferences = [genericM1, genericUnM1, genericK1, genericUnK1, genericU1, genericL1, genericR1, genericProduct];
genericReferenceList :: GenericReferences -> [DerivingReference];
genericReferenceList references = map ($ references) (genericTermReferences <> types <> promoted) where {
  types = [genericV1Type, genericU1Type, genericSumType, genericProductType, genericD1Type, genericC1Type, genericS1Type, genericRec0Type];
  promoted = [genericMetaData, genericMetaCons, genericMetaSel, genericPrefixI, genericInfixI, genericLeftAssociative, genericRightAssociative, genericNotAssociative, genericNoSourceUnpackedness, genericSourceNoUnpack, genericSourceUnpack, genericNoSourceStrictness, genericSourceLazy, genericSourceStrict, genericDecidedLazy, genericDecidedStrict, genericDecidedUnpack]};
derivingReferenceList :: DerivingReferences -> [DerivingReference];
derivingReferenceList references = [derivingTrue references, derivingFalse references, derivingLT references, derivingEQ references, derivingGT references, derivingIntCon references, derivingIntPrimType references, derivingGreaterOrEqual references, derivingCons references, derivingBind references, derivingThen references, derivingReturn references, derivingReadParens references, derivingReadPrecContext references, derivingReadStep references, derivingReadReset references, derivingReadAlternative references, derivingReadFail references, derivingReadExpect references, derivingReadField references, derivingReadSymField references, derivingLexemeIdent references, derivingLexemeSymbol references, derivingLexemePunc references, derivingPure references, derivingApply references, derivingLiftConE references, derivingLiftAppE references, derivingLiftDataConName references, derivingLiftCodeCoerce references] <> genericReferenceList (derivingGeneric references)
}
